-- Salary ledger lookup and employee linkage.
-- Source: Supabase Snippet Fetch Accounts by Salary Group.csv (369 rows).
-- Idempotent: safe to apply more than once and never changes existing employee links.

CREATE TABLE IF NOT EXISTS public.salary_ledgers (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_name TEXT NOT NULL,
  account_code TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS salary_ledgers_account_name_idx
  ON public.salary_ledgers (LOWER(account_name));

ALTER TABLE public.employees
  ADD COLUMN IF NOT EXISTS salary_ledger_id INTEGER;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'employees_salary_ledger_id_fkey'
  ) THEN
    ALTER TABLE public.employees
      ADD CONSTRAINT employees_salary_ledger_id_fkey
      FOREIGN KEY (salary_ledger_id) REFERENCES public.salary_ledgers(id)
      ON DELETE SET NULL;
  END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS employees_salary_ledger_id_key
  ON public.employees (salary_ledger_id);

ALTER TABLE public.salary_ledgers ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS salary_ledgers_authenticated_access ON public.salary_ledgers;
CREATE POLICY salary_ledgers_authenticated_access
  ON public.salary_ledgers FOR SELECT TO authenticated USING (true);

